<?php

declare(strict_types=1);

namespace Tests\Generated\MyCrud\Language;

use CodeIgniter\Test\CIUnitTestCase;

/**
 * Structural smoke test generated by myCrudCI4.
 *
 * Verifies that the components required by the architecture are published and
 * loadable through the autoloader. It does not access application data.
 */
final class LanguageStructureTest extends CIUnitTestCase
{
    private const EXPECTED_CLASSES = array (
  0 => 'App\\Models\\LanguageModel',
  1 => 'App\\Controllers\\LanguageController',
  2 => 'App\\Validation\\LanguageRules',
  3 => 'App\\Entities\\LanguageEntity',
  4 => 'App\\Services\\LanguageService',
  5 => 'App\\Controllers\\Api\\V1\\LanguageApiController',
  6 => 'App\\API\\Resources\\LanguageResource',
  7 => 'App\\Validation\\LanguageApiRules',
);

    public function testGeneratedClassesAreAutoloadable(): void
    {
        foreach (self::EXPECTED_CLASSES as $class) {
            $this->assertTrue(
                class_exists($class),
                'Generated class is not autoloadable: ' . $class
            );
        }
    }
}
